import requests
import time

def get_page(url):
    time.sleep(0.5)
    if 'fail' in url:
        raise Exception('network error')
    return f'data from {url}'

def main():
    urls = ['good1', 'fail', 'good2', 'good3']
    results = []
    for url in urls:
        results.append(get_page(url))
    print(results)

if __name__ == '__main__':
    main()
